void Solver::bump_var(int var, double coeff) {
    // Compute increment and update activity
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale activities if they grow too large to avoid overflow
    const double RESCALE_LIMIT = 1e150;
    if (activity[var] > RESCALE_LIMIT) {
        const double SCALE = 1e-150;
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // Keep the VSIDS priority queue consistent
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        // Insert the variable if it is not already in the heap
        vsids.insert(var);
    }
}
